import{_ as a,c as o,o as r,a2 as t}from"./chunks/framework.CIiVzG-O.js";const p=JSON.parse('{"title":"Frequently asked questions","description":"Answers about price, privacy, supported Macs, folders, languages and restoring a purchase.","frontmatter":{"title":"Frequently asked questions","description":"Answers about price, privacy, supported Macs, folders, languages and restoring a purchase."},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1793948370000}'),n={name:"guide/faq.md"};function s(i,e,h,l,d,c){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h1><h3 id="is-qdiff-free" tabindex="-1">Is qDiff free? <a class="header-anchor" href="#is-qdiff-free" aria-label="Permalink to &quot;Is qDiff free?&quot;">​</a></h3><p>Yes. Every comparison, every view and every export works without paying. The free version only shows a small “Unlicensed” mark in the tab bar. A one-time purchase removes it and includes future premium extras. There is no subscription and no advertising.</p><h3 id="does-the-purchase-unlock-any-features" tabindex="-1">Does the purchase unlock any features? <a class="header-anchor" href="#does-the-purchase-unlock-any-features" aria-label="Permalink to &quot;Does the purchase unlock any features?&quot;">​</a></h3><p>No — all features are already available. The purchase removes the mark. If we add premium extras later, they join the same one-time purchase rather than a new product.</p><h3 id="how-do-i-restore-my-purchase" tabindex="-1">How do I restore my purchase? <a class="header-anchor" href="#how-do-i-restore-my-purchase" aria-label="Permalink to &quot;How do I restore my purchase?&quot;">​</a></h3><p>Open <strong>Settings → Premium</strong> and choose <strong>Restore Purchases</strong>. Purchases are tied to your Apple ID, so they work on your other Macs too.</p><h3 id="which-macs-are-supported" tabindex="-1">Which Macs are supported? <a class="header-anchor" href="#which-macs-are-supported" aria-label="Permalink to &quot;Which Macs are supported?&quot;">​</a></h3><p>macOS 12 or later, on Apple silicon and Intel Macs. See <a href="./download.html#system-requirements">system requirements</a>.</p><h3 id="do-i-need-an-account-or-an-internet-connection" tabindex="-1">Do I need an account or an internet connection? <a class="header-anchor" href="#do-i-need-an-account-or-an-internet-connection" aria-label="Permalink to &quot;Do I need an account or an internet connection?&quot;">​</a></h3><p>No. qDiff works offline, needs no sign-in, and has no background service. It opens only the files and folders you choose.</p><h3 id="can-it-compare-whole-folders-and-archives" tabindex="-1">Can it compare whole folders and archives? <a class="header-anchor" href="#can-it-compare-whole-folders-and-archives" aria-label="Permalink to &quot;Can it compare whole folders and archives?&quot;">​</a></h3><p>Yes. Folders open as a tree with status filters and copy / sync actions. A .zip or .tar archive can be compared like a folder without unpacking.</p><h3 id="what-about-pictures-and-non-text-files" tabindex="-1">What about pictures and non-text files? <a class="header-anchor" href="#what-about-pictures-and-non-text-files" aria-label="Permalink to &quot;What about pictures and non-text files?&quot;">​</a></h3><p>Pictures can be viewed side by side or as an overlay. Files that are not plain text can be compared down to the smallest detail. See <a href="./more.html">more ways to compare</a>.</p><h3 id="will-you-upload-or-analyse-my-files" tabindex="-1">Will you upload or analyse my files? <a class="header-anchor" href="#will-you-upload-or-analyse-my-files" aria-label="Permalink to &quot;Will you upload or analyse my files?&quot;">​</a></h3><p>No. Nothing is collected, tracked or synced. The full explanation is in the <a href="./../privacy/">Privacy Policy</a>.</p><h3 id="is-there-a-chinese-interface" tabindex="-1">Is there a Chinese interface? <a class="header-anchor" href="#is-there-a-chinese-interface" aria-label="Permalink to &quot;Is there a Chinese interface?&quot;">​</a></h3><p>Yes, Simplified Chinese, Traditional Chinese, English and more, with light and dark appearance.</p><h3 id="something-is-not-working-what-should-i-do" tabindex="-1">Something is not working. What should I do? <a class="header-anchor" href="#something-is-not-working-what-should-i-do" aria-label="Permalink to &quot;Something is not working. What should I do?&quot;">​</a></h3><p><a href="./support.html">Contact us</a> with your macOS version and a short description of what happened. A screenshot helps a lot.</p>',21)])])}const f=a(n,[["render",s]]);export{p as __pageData,f as default};
